create or replace package body atm_api as
  function withdraw(p_account_no in varchar2, p_amount in number) return varchar2 is
    e_limit exception;
    pragma exception_init(e_limit, -20070);
    l_current_balance bank_accounts.balance%type;
    l_overdraft_limit bank_accounts.overdraft_limit%type;
  begin
    -- Fetch current balance and overdraft limit
    select balance, overdraft_limit
    into l_current_balance, l_overdraft_limit
    from bank_accounts
    where account_no = p_account_no;

    -- Check if withdrawal exceeds the allowed limit (current balance + overdraft limit)
    if (l_current_balance - p_amount) < (-l_overdraft_limit) then
      return 'DECLINED';
    end if;

    -- Update balance if within limits
    update bank_accounts
       set balance = balance - p_amount
     where account_no = p_account_no;
    return 'OK';
  exception
    when no_data_found then
      -- Handle case where account is not found, although not explicitly tested, it's good practice
      return 'DECLINED';
    when e_limit then
      return 'DECLINED';
  end withdraw;

  function balance_of(p_account_no in varchar2) return number is
    l_balance bank_accounts.balance%type;
  begin
    select balance into l_balance from bank_accounts where account_no = p_account_no;
    return l_balance;
  end balance_of;
end atm_api;
